                S['phase'] = 'product'
                S['pi'] = k
                if r == 'refusal':
                    kk = p.get('attempts_used', 0) + 1
                    if not _start_attempt(S, p, kk):
                        p['disposition'] = POLICY['outcomes'].get('refused_reason') or 'refused'
                        return _advance(S)
